<?php
require dirname(__DIR__).'/app/bootstrap.php';
$me=require_login();
if(!can('media.upload')&&!can('media.approve')&&!can('media.edit_all')){http_response_code(403);exit('Video library permission required.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();
 try{
  $action=(string)($_POST['action']??'');$id=max(0,(int)($_POST['id']??0));
  if($action==='save'){
   require_permission('media.upload');
   if($id){VideoService::updateDraft($id,$_POST,(int)$me['id'],can('media.edit_all'));audit_log('video_update','video_asset',$id,'draft');flash('Video draft updated. Review metadata, then submit it for independent approval.');}
   else{$id=VideoService::create($_POST,(int)$me['id']);audit_log('video_create','video_asset',$id,'draft');flash('Video draft created. Submit it when rights, accessibility and metadata are complete.');}
   header('Location: '.path('admin/video-library.php?edit='.$id));exit;
  }
  if($action==='submit'){
   require_permission('media.upload');VideoService::submit($id,(int)$me['id'],can('media.edit_all'));audit_log('video_submit','video_asset',$id,'submitted');flash('Video submitted for independent multimedia review.');
  }elseif($action==='approve'){
   require_permission('media.approve');VideoService::approve($id,(int)$me['id']);audit_log('video_approve','video_asset',$id,'approved');flash('Video approved and can now be attached to an article.');
  }elseif($action==='reject'){
   require_permission('media.approve');$reason=(string)($_POST['reason']??'');VideoService::reject($id,(int)$me['id'],$reason);audit_log('video_reject','video_asset',$id,substr(trim($reason),0,1000));flash('Video returned to its creator with a review note.');
  }elseif($action==='archive'){
   require_permission('media.approve');$reason=(string)($_POST['reason']??'');VideoService::archive($id,(int)$me['id'],$reason);audit_log('video_archive','video_asset',$id,substr(trim($reason),0,1000));flash('Video archived. It is no longer eligible for public playback or new article attachment.');
  }else throw new RuntimeException('Unknown video action.');
  header('Location: '.path('admin/video-library.php'));exit;
 }catch(Throwable $e){$error=$e->getMessage();}
}
$editId=max(0,(int)($_GET['edit']??0));$editing=$editId?query_one('SELECT * FROM video_assets WHERE id=?',[$editId]):null;
if($editId&&!$editing){http_response_code(404);$error='Video asset not found.';}
$canEdit=$editing&&in_array((string)$editing['status'],['draft','rejected'],true)&&(can('media.edit_all')||(int)$editing['created_by']===(int)$me['id']);
$assets=query_all('SELECT v.*,creator.full_name AS creator_name,approver.full_name AS approver_name FROM video_assets v JOIN users creator ON creator.id=v.created_by LEFT JOIN users approver ON approver.id=v.approved_by ORDER BY v.created_at DESC LIMIT 250');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Video Library · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="admin-body"><main class="admin-content" style="max-width:1280px;margin:auto"><p><a href="<?=e(path('admin/index.php'))?>">← Newsroom</a> &nbsp;·&nbsp; <a href="<?=e(path('admin/media-library.php'))?>">Image Library</a></p><div class="admin-section-title"><div><span class="overline">CONTROLLED VIDEO PUBLISHING</span><h1>Editorial Video Library<span class="brand-accent">.</span></h1></div><?php if($editing):?><a href="<?=e(path('admin/video-library.php'))?>">+ NEW VIDEO</a><?php endif;?></div><p>YouTube is the currently approved delivery provider. AFRIVOX NEWS stores the reviewed reference, accessibility metadata and publication rights; it does not copy or pretend to transcode the provider’s video file.</p><?php if($error):?><div class="form-error" role="alert"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice" role="status"><?=e($msg)?></div><?php endif;?>

<?php if(can('media.upload')&&(!$editing||$canEdit)):?><section class="setting-panel"><h2><?=$editing?'Edit video draft':'Register a video'?></h2><p>Draft → Submitted → independent multimedia approval → article attachment → public playback.</p><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($editing['id']??0))?>"><label>HTTPS YOUTUBE URL<input type="url" name="source_url" maxlength="500" required placeholder="https://www.youtube.com/watch?v=..." value="<?=e($editing['source_url']??'')?>"></label><label>TITLE<input name="title" minlength="5" maxlength="240" required value="<?=e($editing['title']??'')?>"></label><label>DESCRIPTION<textarea name="description" rows="3" maxlength="5000"><?=e($editing['description']??'')?></textarea></label><label>ACCESSIBLE DESCRIPTION / ALT TEXT<input name="alt_text" minlength="10" maxlength="500" required value="<?=e($editing['alt_text']??'')?>"></label><label>LANGUAGE<select name="language"><?php foreach(['rw'=>'Kinyarwanda','en'=>'English','fr'=>'Français','multi'=>'Multilingual'] as $value=>$label):?><option value="<?=$value?>" <?=($editing['language']??'rw')===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>DURATION IN SECONDS<input type="number" name="duration_seconds" min="0" max="86400" value="<?=e((string)($editing['duration_seconds']??''))?>"></label><label class="checkline"><input type="checkbox" name="captions_available" value="1" <?=!empty($editing['captions_available'])?'checked':''?>> Provider captions have been checked and are available</label><label>TRANSCRIPT (required when captions are not confirmed)<textarea name="transcript_text" rows="8" maxlength="200000"><?=e($editing['transcript_text']??'')?></textarea></label><label>RIGHTS HOLDER<input name="rights_holder" maxlength="240" required value="<?=e($editing['rights_holder']??'')?>"></label><label>LICENCE / CONTRACT REFERENCE<input name="license_reference" maxlength="500" required value="<?=e($editing['license_reference']??'')?>"></label><label>RIGHTS EXPIRE<input type="datetime-local" name="rights_expires_at" value="<?=e(!empty($editing['rights_expires_at'])?date('Y-m-d\TH:i',strtotime((string)$editing['rights_expires_at'])):'')?>"></label><label>USAGE RESTRICTIONS<textarea name="usage_restrictions" rows="3" maxlength="5000"><?=e($editing['usage_restrictions']??'')?></textarea></label><button type="submit">SAVE VIDEO DRAFT →</button></form></section><?php endif;?>

<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>VIDEO</th><th>ACCESSIBILITY</th><th>RIGHTS</th><th>WORKFLOW</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($assets as $asset):?><tr><td><b><?=e($asset['title'])?></b><br><small><?=e(strtoupper($asset['language']))?> · <?=e($asset['provider'])?> · <?=e($asset['provider_video_id'])?></small><br><a href="<?=e($asset['source_url'])?>" target="_blank" rel="noopener noreferrer">Open provider ↗</a></td><td><?=!empty($asset['captions_available'])?'Captions confirmed':'Transcript supplied: '.(mb_strlen(trim((string)$asset['transcript_text']))>=20?'yes':'no')?><br><small><?=e($asset['alt_text'])?></small></td><td><?=e($asset['rights_holder'])?><br><small><?=e($asset['license_reference'])?><?php if($asset['rights_expires_at']):?> · expires <?=e(display_date($asset['rights_expires_at']))?><?php endif;?></small></td><td><span class="status-pill <?=e($asset['status'])?>"><?=e($asset['status'])?></span><br><small>Created by <?=e($asset['creator_name'])?><?php if($asset['approver_name']):?> · reviewed by <?=e($asset['approver_name'])?><?php endif;?></small><?php if($asset['review_note']):?><br><b><?=e($asset['review_note'])?></b><?php endif;?></td><td><?php if(in_array($asset['status'],['draft','rejected'],true)&&(can('media.edit_all')||(int)$asset['created_by']===(int)$me['id'])):?><a href="<?=e(path('admin/video-library.php?edit='.$asset['id']))?>">EDIT</a><form method="post" style="margin-top:.5rem"><?=csrf_field()?><input type="hidden" name="action" value="submit"><input type="hidden" name="id" value="<?=$asset['id']?>"><button type="submit">SUBMIT</button></form><?php endif;?><?php if(can('media.approve')&&$asset['status']==='submitted'&&(int)$asset['created_by']!==(int)$me['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=$asset['id']?>"><button type="submit">APPROVE</button></form><form method="post" style="margin-top:.5rem"><?=csrf_field()?><input type="hidden" name="action" value="reject"><input type="hidden" name="id" value="<?=$asset['id']?>"><input name="reason" minlength="10" maxlength="1000" placeholder="Review reason" required><button type="submit">REJECT</button></form><?php endif;?><?php if(can('media.approve')&&in_array($asset['status'],['approved','rejected'],true)):?><form method="post" style="margin-top:.5rem"><?=csrf_field()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=$asset['id']?>"><input name="reason" minlength="10" maxlength="1000" placeholder="Archive / takedown reason" required><button type="submit">ARCHIVE</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$assets):?><p class="empty-state">No videos are registered yet.</p><?php endif;?></div></main></body></html>
